INSERT IGNORE INTO `meal_item` (source_type, owner_user_id, name, name_en, aliases, meal_time, mood, scene, health_goal, cuisine, taste, convenience, description, ingredients_json, serving_count, serving_size, serving_unit, calories_kcal, protein_g, fat_g, carbohydrate_g, nutrition_basis, nutrition_estimated, allergen_json, allergen_status, review_status, source_name, source_id, source_version, media_url, media_status, media_credit, created_at, updated_at) VALUES
('PUBLIC', NULL, '黑豆千层面', 'Black Bean Lasagna', '["豆香千层面"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '["咸鲜", "辣"]', '["慢享"]', 'This Lasagna is a good Vegetarian dish. It can be made ahead up to 1 day and baked as directed or , freeze up to 1 month; thaw frozen casserole in fefrigerator overnight, and bake for 40 to 45 minutes or until heated through. The recipe comes from Better Homes & Gardens.com.', '["black beans", "onion", "green sweet pepper", "garlic cloves", "tomato sauce", "tomato sauce", "cilantro", "low fat cottage cheese", "reduced-fat cream cheese", "light sour cream", "tomatoes", "fresh cilantro leaves"]', 8, '1.00', '份', '332.70', '19.30', '7.20', '49.10', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '100332', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '辣味三芝士墨西哥意面', 'Spicy Low Fat 3-cheese Pasta With Chipotle', '["芝士墨西哥意面"]', '["午餐", "晚餐"]', '[]', '[]', '[]', '[]', '["辣"]', '["快速"]', 'Rich, hearty and spicy but low in fat! The filling tasty pasta you love without the guilt. Easy and fresh with easy to find ingredients. Only 7 WW points! Vegetarian, too!', '["light margarine", "onion", "bell pepper", "zucchini", "garlic", "chipotle chiles in adobo", "flour", "tomatoes and green chilies", "cooked pasta", "low-fat cheddar cheese", "fat-free cottage cheese", "parmesan cheese", "egg", "nonfat milk"]', 6, '1.00', '份', '297.70', '21.70', '5.90', '40.00', 'foodcom_source_value', '1', '["牛奶", "鸡蛋", "麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '100900', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '西班牙米饭酿彩椒', 'Bell Peppers Stuffed With Spanish Rice, Low Fat/Low Carb', '["米饭彩椒"]', '["三餐"]', '[]', '[]', '["均衡"]', '[]', '[]', '[]', 'The caloric value of this changed from 381 a serving to 171 a serving; 22 grams of fat to 3 grams of fat. This tastes like a million dollars also.', '["green peppers", "ground turkey", "onion", "cooked brown rice", "stewed tomatoes", "tomato paste", "Worcestershire sauce", "dried basil", "salt", "ground black pepper", "low-fat cheddar cheese"]', 4, '1.00', '份', '205.60', '14.60', '5.90', '24.70', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '102952', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '香蕉面包', 'Tasty Banana Bread', '["香蕉蛋糕", "Banana Bread"]', '["下午茶", "早餐"]', '[]', '[]', '["低油", "均衡"]', '["甜品"]', '[]', '["快速", "慢享"]', 'I like this recipe because it is easy to make and has a stronger taste of banana than most banana breads. It is also a low calorie, low fat recipe. It creates a tasty, chewy on the edges banana bread. This recipe comes from a Better Homes and Gardens Cookbook titled "New Dieter''s Cookbook". You can also make this vegan by substituting one medium banana mashed/beaten till liquidy or 1 tablespoon ground flax seed plus 3 tablespoons water for the egg whites. It is very delicous and moist any way you decide to make it.', '["all-purpose flour", "baking powder", "baking soda", "ground cinnamon", "salt", "sugar", "canola oil"]', 16, '1.00', '份', '124.10', '1.80', '3.60', '21.70', 'foodcom_source_value', '1', '["鸡蛋", "麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '103004', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '低碳墨西哥烤鸡', 'Low Carb Mexi Baked Chicken', '["墨西哥烤鸡"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '[]', '["奶香"]', '["快速"]', 'Another personal South Beach Diet friendly favorite of mine. It''s flavorful and easy to throw together, bakes in less than 1 hour. I serve this with a side of my Mexican Jumping Beans. For the taco seasoning, I like to make my own (no sugar added; there are plenty of taco seasoning Zaar recipes to choose from, if you would like to make your own.', '["boneless skinless chicken breasts", "salsa", "low-fat cheddar cheese"]', 2, '1.00', '份', '197.30', '31.90', '5.00', '5.10', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '103966', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '烧烤鸡肉串', 'BBQ Chicken Kebabs', '["BBQ 鸡肉串"]', '["三餐"]', '[]', '[]', '["均衡", "高蛋白"]', '[]', '["辣"]', '["快速"]', 'Tangy and flavorful. You may also do these skewers in the oven 325 F apprx 20 min. check to see that no pink remains when cut through. If you do not like yogurt use sour cream or whipped cottage cheese with a couple of tbsp of low fat cream cheese added. A short cut to the final BBQ time is to partially cook the chicken in the marinade in a skillet until the chicken is just beginning to brown, then thread it onto the skewers and keep in fridge until you are ready to BBQ - only takes 10 minutes on a pre heated grill. Do not miss squeezing the fresh lime juice on as you are BBQing them - it gives a lovely zing.', '["boneless skinless chicken breasts", "nonfat yogurt", "garlic cloves", "fresh ginger", "curry powder", "granulated sugar", "salt", "cayenne pepper", "fresh lime juice", "lime wedges"]', 4, '1.00', '份', '162.50', '29.40', '1.70', '6.30', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '10405', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '番茄芝士焗', 'Tomatoes Maximilien', '["番茄焗菜", "Tomatoes Maximilien"]', '["午餐", "晚餐"]', '[]', '[]', '[]', '[]', '["奶香"]', '["慢享"]', 'This recipe is from a French recipe book and is quite healthy (apart from the cream sauce and the cheese, but you can use a low fat version). The original recipe uses "oseille" herb for the sauce but it is not easy to find, so I use the lemon juice as a replacement. These tomatoes are to die for and will also delight vegetarians (just omit the eggs).', '["eggs", "tomatoes", "carrots", "leeks", "garlic clove", "parsley", "cheese", "salt", "pepper", "olive oil"]', 4, '1.00', '份', '337.80', '15.20', '21.30', '23.70', 'foodcom_source_value', '1', '["牛奶", "鸡蛋"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '104206', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '鳎鱼菠菜砂锅', 'Sole and Spinach Casserole', '["龙利鱼菠菜焗"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '[]', 'An easy and light recipe from Barbara Gibbons, ''The Slim Gourmet''. Although I haven''t tried this, I''m sure it will appeal to calorie counters as well as those on low-carb diets. Let me know what you think!', '["fresh spinach", "frozen chopped spinach", "onions", "nonfat milk", "light cheddar cheese", "sole fillets", "lemon juice", "paprika"]', 4, '1.00', '份', '209.50', '34.70', '4.10', '10.00', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '104322', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '低脂鸡肉蔬菜小炒', 'Low-Fat Chicken and Veggie Saute', '["鸡胸蔬菜炒"]', '["三餐"]', '[]', '[]', '["低油", "均衡", "控碳水"]', '[]', '[]', '["快速"]', 'I came up with this last night, using some ingredients I had on hand, and it was WONDERFUL!! I ate half for dinner last night over brown rice, and took the rest for lunch and ate just by itself. Very filling and healthy!', '["garlic", "chicken broth", "boneless skinless chicken breasts", "roma tomatoes", "fresh mushrooms", "green onions", "fresh spinach", "dried parsley", "oregano", "basil", "salt", "ground black pepper"]', 2, '1.00', '份', '204.90', '32.60', '2.60', '14.40', 'foodcom_source_value', '1', '["鸡蛋"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '104865', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '奶油黄油豆汤', 'Coco - Banana''s Creamless Cream of Butter Bean and Herb Soup', '["植物奶油豆汤"]', '["三餐"]', '[]', '[]', '["低油", "均衡", "高蛋白"]', '["素食"]', '[]', '["快速", "慢享"]', 'This recipe is a light, refreshing soup perfect for spring and summer. I am not one for creamy things, and this is not rich at all. It is adapted from veganchef.com (Butterbean and Herb Cream Soup)', '["dried lima beans", "bay leaf", "fresh parsley", "fresh chives", "fresh basil", "sea salt"]', 4, '1.00', '份', '304.80', '19.50', '0.70', '57.10', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '104869', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '香草奶油酱鸡肉', 'Chicken With Creamy Herb Sauce', '["奶油香草鸡"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '[]', '[]', '[]', 'Make and share this Chicken With Creamy Herb Sauce recipe from Food.com.', '["boneless skinless chicken breast halves", "dried oregano", "salt", "pepper", "garlic cloves", "low-fat buttermilk", "fresh parsley", "water", "dried thyme", "salt", "pepper"]', 6, '1.00', '份', '174.90', '24.70', '5.50', '4.50', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '10570', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '希腊羊奶酪鸡肉', 'Greek Feta Chicken', '["Feta 鸡肉"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '[]', '[]', '[]', 'Make and share this Greek Feta Chicken recipe from Food.com.', '["plain low-fat yogurt", "lemon juice", "dried oregano", "dried rosemary", "pepper", "garlic clove", "boneless skinless chicken breast halves", "feta cheese", "feta cheese", "fresh parsley"]', 4, '1.00', '份', '202.40', '29.00', '6.60', '5.30', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '10600', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '爱尔兰土豆泥', 'Irish Mashed Potatoes', '["土豆泥", "Irish Mashed"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["快速"]', 'The leeks give a mild onion flavor to the potatoes. This is a reasonably low cal. recipe. If you wish this recipe to be strict vegetarian/vegan use soy milk or vegetable broth instead of milk', '["potatoes", "leek", "low-fat milk", "lite olive oil"]', 4, '1.00', '份', '200.10', '5.80', '4.20', '35.90', 'foodcom_source_value', '1', '["牛奶", "大豆"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '10974', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '活力沙拉', 'Rejuvenation Salad', '["凉拌时蔬"]', '["早午餐"]', '[]', '[]', '[]', '[]', '[]', '["快速"]', 'mmmmmmmmm Salad. One of my favorite foods. Salads are traditionally low calorie, low fat, low sugar, etc... it''s what you put ON the salad that makes it soooo wonderfully tasty and fattening too. This salad is fantastic year round and is very easy on the hips. As with any dressing, the more oil and oil products you use to make it with the more fattening it is... this is one very light and very delicious salad with dressing you''ll love. This is a big salad and can be altered to make a smaller salad, but don''t forget you can always enjoy the leftovers tomorrow.', '["iceberg lettuce", "romaine lettuce", "grape tomatoes", "celery", "spinach", "cauliflower", "broccoli", "fresh parsley sprig", "carrot", "garlic", "lime, juice of", "shallots", "Splenda sugar substitute", "green grapes", "salt", "peppercorn", "plain low-fat yogurt"]', 12, '1.00', '份', '23.30', '1.00', '0.20', '5.40', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '110711', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '古斯米虾仁', 'Shrimp With Couscous', '["虾仁古斯米"]', '["三餐"]', '[]', '[]', '[]', '[]', '[]', '["快速"]', 'I originally got this recipe from the food section of the Houston chronicle. We like it because it''s quick and easy to make, is fairly low calorie and low fat and VERY tasty!', '["olive oil", "shrimp", "coarse salt", "ground black pepper", "mustard seeds", "leeks", "carrots", "garlic", "couscous", "frozen baby peas", "boiling water"]', 6, '1.00', '份', '312.60', '29.60', '6.30', '33.00', 'foodcom_source_value', '1', '["麸质", "甲壳类"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '111622', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '罗勒酱煎鳕鱼', 'Pan-seared Cod With Basil Sauce', '["香煎鳕鱼"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '["海鲜"]', '["咸鲜"]', '["快速"]', 'This has a fresh pesto-like feel without the nuts, and a lot less fat. Any flaky white fish can be used here - I usually have tilapia or whitefish around rather than cod. I had an open bottle of Reisling and so I used that in place of the broth. From Cooking Light.', '["fresh basil", "reduced-sodium chicken broth", "parmesan cheese", "olive oil", "salt", "garlic cloves", "cod fish fillets", "black pepper"]', 4, '1.00', '份', '196.70', '32.00', '6.50', '0.90', 'foodcom_source_value', '1', '["牛奶", "鱼"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '112259', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '孜然脆皮海鲈鱼', 'Cumin Crusted Chilean Sea Bass', '["孜然海鲈鱼"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '["海鲜"]', '[]', '["快速"]', 'I love cumin, and am looking forward to trying this one out! This was shared by Sue Z Q on Gail’s. Adapted from Cooking Light, Dec. 2001.', '["cumin seed", "salt", "fresh ground black pepper", "sea bass fillets", "olive oil", "butter", "fresh parsley", "lemon wedges"]', 4, '1.00', '份', '189.90', '32.10', '5.40', '2.40', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '117145', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '中东风味烤土豆', '" Middle Eastern " Twice-Baked Potatoes', '["中东烤土豆"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["慢享"]', 'A delicious yet low-fat twice-baked potato side dish with a blend of classic Middle Eastern flavours: chickpeas, cumin and coriander. Serve with roasts or with your favourite Middle Eastern main course dish. Adapted from "Practical Cookery: low fat". These potatoes could also be served on their own as a light vegetarian meal. In view of the comments by reviewers about the potatoes being a bit dry, I have added a tablespoon of tahini. I have also added some garlic. I''m not sure how the recipe escaped having garlic in it when I first posted it!', '["baking potatoes", "olive oil", "chickpeas", "ground cumin", "fresh coriander", "garlic cloves", "low-fat yogurt", "tahini"]', 4, '1.00', '份', '327.60', '10.90', '7.30', '56.30', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '120297', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '美味素食法士达', 'Delicious Vegetarian Fajita - Healthy', '["素菜卷饼", "Fajita"]', '["午餐", "晚餐"]', '[]', '[]', '[]', '[]', '[]', '["快速"]', 'This is very healthy, simple and easy to make. You can buy the menudo spice in any grocery store. Just look in the mexican food aisle. I prefer to serve it with Mission''s extra thin corn tortillas (lower calorie), because you can slightly warm them in the pan and they will soften. Or try the low carb flour tortilla for extra fiber.', '["green bell pepper", "red bell pepper", "orange bell peppers", "yellow bell pepper", "red onions", "garlic cloves", "cumin", "salt", "black pepper", "lemon pepper", "fresh cilantro"]', 8, '1.00', '份', '84.30', '0.80', '6.90', '5.80', 'foodcom_source_value', '1', '["麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '120612', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '红辣椒鸡肉煲', 'Red Chicken Chili', '["鸡肉辣椒", "Red Chili"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["慢享"]', 'I love chicken chili and this one is a little different. Adapted from Cooking Light. Serving size: 1 cup chili, 1 T. cheese, and 1 T. sour cream. 280 calories, 9.2 g fat, 26.6 g carb, 5.4 g fiber, 54 mg cholesterol', '["olive oil", "onions", "chili powder", "dried oregano", "ground cumin", "salt", "garlic cloves", "kidney beans", "whole tomatoes", "low-fat cheddar cheese", "low-fat sour cream"]', 8, '1.00', '份', '260.30', '22.20', '9.30', '23.20', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '120651', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '孜然番茄玉米汤', 'Cumin-scented Tomato and Corn Soup', '["番茄玉米汤"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["快速"]', 'This is a quick and easy cold soup that makes use of summer''s ripe tomotoes and fresh corn.Using ice cubes in the preparation cools it quickly and it''s low calorie and low fat- a real plus!Vary the flavor by using cilantro one time and basil the next- we like both!Sometimes I add use a mixture of red and green bell peppers to add more color. Originally from the food section of the Houston Chronicle.', '["tomatoes", "scallion", "fresh basil", "cilantro", "garlic clove", "ground cumin", "green bell pepper", "fresh lime juice", "salt", "fresh ground pepper", "avocado", "scallion tops"]', 4, '1.00', '份', '63.30', '2.90', '0.80', '13.80', 'foodcom_source_value', '1', '[]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '121199', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '芝士香葱司康', 'Cheese and Chive Scones', '["芝士司康", "Scones"]', '["下午茶", "早午餐", "早餐"]', '[]', '[]', '["均衡"]', '["甜品"]', '[]', '["快速"]', 'A delicious low-calorie, low-fat version of the Classic Cheese and Chive Scones with healthy low-fat alternatives in the inclusion of the low-fat soft cheese and the skimmed milk. If you wish, you can also use reduced-fat cheddar, but this will seriously compromise the flavour in a way that the other two low fat alternatives do not. Adapted from Parragon''s ''Low Fat''.', '["self-raising flour", "mustard powder", "cayenne pepper", "salt", "chives", "skim milk", "cheddar cheese"]', 6, '1.00', '份', '205.90', '10.50', '4.90', '29.10', 'foodcom_source_value', '1', '["牛奶", "麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '121716', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '农夫市集砂锅', 'Farmer''s Market Casserole', '["时蔬焗菜"]', '["午餐", "晚餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '["奶香"]', '["慢享"]', 'Another wonderful recipe from my favorite award-winning cookbook and a great way to create a colorful and tasty concoction while using up some of your fresh garden vegetables. Nice vegetarian main meal for two or side dish for four. Be sure to use a shallow casserole so vegetables are tender in allotted time. Note that this may be prepared a couple of hours ahead, up to last cooking interval, if left at room temperature. (This recipe comes from a cookbook of the UP area of Michigan, which could be construed as Canada, so I''m submitting this for Zaar World Tour Canadian recipes.)', '["potatoes", "onion", "zucchini", "tomatoes", "carrots", "thyme", "marjoram", "dry white wine", "butter", "low-fat sharp cheddar cheese"]', 4, '1.00', '份', '383.40', '20.50', '7.70', '52.10', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '123402', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
