('PUBLIC', NULL, '豆腐酿彩椒', 'Tofu-Stuffed Bell Peppers With a Twist', '["豆腐彩椒"]', '["三餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["慢享"]', 'A flavorful, hearty main that is low fat and vegan. The "twist" is foregoing tomato sauce and including eggplant and chili powder to the filling instead. The filling holds together better than most eggless mixtures of this type and could also be used as a vegetarian loaf. Some nuts or seeds would be a good addition to the filling to provide textural contrast.', '["brown rice", "eggplant", "firm tofu", "garlic cloves", "scallions", "olive oil", "chili powder", "salt", "pepper", "bell peppers", "cornstarch", "vegetable broth"]', 4, '1.00', '份', '290.80', '13.50', '9.30', '42.60', 'foodcom_source_value', '1', '["鸡蛋", "大豆"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '280208', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '绿酱鸡肉白辣椒', 'South Beach Diet Tomatillo White Chili', '["番茄绿辣椒", "White Chili"]', '["三餐"]', '[]', '[]', '[]', '["西餐"]', '[]', '["慢享"]', 'A golden & delicious white chili with a tangy tomatillo kick. This is a hearty stew type soup, full of vegetables and beans. It''s extremely healthy: low fat, low cholesterol and low carb but full of taste! Excellent for phase 1 of the South Beach Diet! Easy to prepare using whatever green, white or yellow ingredients you have on hand (it''s especially good using chopped jicama if you have it). If using a crockpot cook for 4 hours on high or 6 hours on low. Excellent served sprinkled with low fat cheddar or mexican cheese blend.', '["boneless skinless chicken breast", "onion", "ground cumin", "garlic cloves", "green peppers", "celery", "salsa verde", "cannellini beans", "white hominy", "salt", "olive oil", "yellow tomatoes", "jicama", "oregano", "fresh cilantro"]', 10, '1.00', '份', '298.40', '23.10', '3.70', '44.30', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '280313', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '卡津鸡腿', 'Cajun Chicken Thighs', '["Cajun 烤鸡腿"]', '["三餐"]', '[]', '[]', '["均衡", "控碳水", "高蛋白"]', '["西餐"]', '[]', '["快速"]', 'Make and share this Cajun Chicken Thighs recipe from Food.com.', '["light brown sugar", "paprika", "dried thyme", "dried oregano", "fresh coarse ground black pepper", "kosher salt", "boneless skinless chicken thighs", "extra virgin olive oil"]', 8, '1.00', '份', '290.50', '45.40', '9.10', '4.30', 'foodcom_source_value', '1', '[]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '281188', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '参议院白豆汤', 'The Famous Senate Restaurant Bean Soup', '["火腿豆汤"]', '["三餐"]', '[]', '[]', '["均衡", "高蛋白"]', '[]', '[]', '["快速", "慢享"]', 'Whatever uncertainties may exist in the Senate of the United States, one thing is sure: Bean Soup is on the menu of the Senate Restaurant every day. The origins of this culinary decree has been lost in antiquity, but there are several oft-repeated legends. One story has it that Senator Fred Thomas Dubois of Idaho, who served in the Senate from 1901 to 1907 and sat as chairman of the committee that supervised the Senate Restaurant, gaveled through a resolution requiring that the bean soup be on the menu every day. Another account attributes the bean soup mandate to Senator Knute Nelson of Minnesota, who expressed his fondness for it in 1903. In any case, Senators, and their guests, are always assured of this hearty, nourishing dish. They know they can rely upon its delightful flavor and epicurean qualities. (Recipe from the Honourable and Mrs. John D. Rockefeller, IV, U.S. Senator, West Virginia.)', '["navy beans", "smoked ham hocks", "onion", "unsalted butter", "salt", "pepper"]', 8, '1.00', '份', '347.00', '33.50', '9.60', '30.80', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '28131', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
