('PUBLIC', NULL, '菠菜鸡胸肉', 'Spinach Chicken Breast', '["菠菜鸡胸"]', '["加餐", "午餐"]', '[]', '[]', '["控碳水", "高蛋白"]', '[]', '["咸鲜"]', '["快速"]', 'This is a quick and easy meal for lunch or supper. Its healthy and tasty! I made it up one night for supper for me and my sister. It was really quick, tasty and not too filling, but just right. It is healthy and spinach actually has more nutrients than any other food! If you want it even healthier, try whole wheat noodles rather than white. I am not too fond of measurements so these are close but approximates, so feel free to adjust as necessary. Enjoy this simple meal as a light, healthy new recipe!', '["chicken breasts", "garlic clove", "onion", "frozen chopped spinach", "parmesan cheese", "tarragon", "lemon juice", "fettuccine pasta"]', 2, '1.00', '份', '271.00', '31.90', '13.70', '4.10', 'foodcom_source_value', '1', '["牛奶", "麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '283465', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '清蒸鱼', 'Basic Steamed Fish', '["蒸鱼", "Basic Steamed Fish"]', '["午餐", "晚餐"]', '[]', '[]', '["均衡", "控碳水", "清淡", "高蛋白"]', '[]', '[]', '["快速"]', 'I got this from About.com. I am looking for more recipes to use with my new bamboo steamer. I have a 2 layer steamer, so I was able to put the fish on the bottom rack and vegetables on the top and dinner was done in 10 minutes! I used tilapia fillets.', '["mirin", "granulated sugar", "salt", "green onion", "cilantro", "lemon"]', 4, '1.00', '份', '146.60', '26.30', '2.90', '3.90', 'foodcom_source_value', '1', '["鱼"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '283704', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
