('PUBLIC', NULL, '烤天贝蔬菜汉堡', 'Grilled Tempeh Veggie Burgers', '["天贝汉堡", "Tempeh Burger"]', '["加餐", "午餐"]', '[]', '[]', '["低油", "均衡"]', '[]', '[]', '["快速"]', 'This protein-rich vegetarian (vegan) recipe is from "Cooking Light Magazine". Chill the tempeh well before slicing so it will be less apt to crumble. This recipe requires at least 3 hours of marinating, the longer the better. Serve with whole-grain burger buns, and whatever toppings you enjoy!', '["tempeh", "water", "low sodium soy sauce", "fresh ginger", "garlic clove"]', 4, '1.00', '份', '247.80', '21.80', '14.50', '12.20', 'foodcom_source_value', '1', '["鸡蛋", "大豆"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '348857', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '塔巴斯科辣椒罗非鱼', 'Chili Tabasco Tilapia', '["辣椒罗非鱼"]', '["三餐"]', '[]', '[]', '["均衡", "高蛋白"]', '[]', '[]', '["快速", "慢享"]', 'This recipe was inspired by a meal I enjoyed at a restaurant recently. I asked our waiter for the recipe, but all he would tell me is that the sauce contained chili sauce over a glaze. It was the perfect combination of sweet and heat, so I tried to duplicate it at home. Using Tabasco Sweet and Spicy gives the fish its slightly sweet flavor. This recipe was featured in an article in the St Louis Post-Dispatch about me and my book, Living the Thin Life. While this specific recipe isn''t in my book, there are many similar healthy, tasty recipes included. Please visit my website, www.livingthethinlife.com, for more information.', '["olive oil", "lime juice", "chili sauce", "Tabasco sauce", "Tabasco sauce", "salt"]', 4, '1.00', '份', '203.50', '34.50', '6.30', '2.00', 'foodcom_source_value', '1', '["鱼"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '349905', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
