('PUBLIC', NULL, '塔可沙拉', 'Taco Salad (Light and Healthy)', '["墨西哥沙拉", "Taco Salad"]', '["三餐"]', '[]', '[]', '[]', '[]', '[]', '["快速"]', 'I love taco salad, but it can be very high in fat and salt. Use the leanest ground beef you can find. Combining the beef with water keeps the crumbles nice and small as it cooks. This is also delicious substituting lean ground turkey for the beef. Reduce or increase jalepeno and cayenne to suit your taste.', '["low-fat flour tortillas", "water", "chili powder", "cumin", "cayenne pepper", "garlic powder", "seasoning salt", "pinto beans", "tomato sauce", "lettuce", "cucumber", "tomatoes", "scallions", "fresh cilantro", "sharp cheddar cheese", "salsa", "fat free sour cream"]', 6, '1.00', '份', '326.60', '29.80', '9.90', '31.40', 'foodcom_source_value', '1', '["牛奶", "麸质"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '415047', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
