('PUBLIC', NULL, '鹰嘴豆蔬菜咖喱', 'Chickpea and Vegetable Curry', '["素咖喱"]', '["三餐"]', '[]', '[]', '[]', '["东南亚菜"]', '["咸鲜", "辣"]', '[]', 'A healthy tasty vegetarian curry. Low in fat, gluten-free and dairy free. Perfect for lunch or dinner. Recipe from Teresa Cutter.', '["onions", "garlic", "curry powder", "chickpeas", "cauliflower", "broccoli", "tomatoes", "firm tofu", "red miso", "boiling water"]', 4, '1.00', '份', '349.10', '23.60', '6.20', '59.40', 'foodcom_source_value', '1', '["麸质", "大豆"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '83737', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
('PUBLIC', NULL, '香菇酱油鸡', 'Chicken in Soy Mushroom Sauce', '["酱香鸡肉"]', '["三餐"]', '[]', '[]', '["控碳水", "清淡"]', '[]', '[]', '["慢享"]', 'This is a really tasty, low fat dish. If you don''t have time to marinade the chicken, don''t bother. It really needs at least one hour, even better with longer. It comes from a Family Circle cookbook entitled "healthy eating". Cooking time is listed as the marinading time. This is not the kind of dish that you can run off and do other things while cooking it. You really do need to stand there..', '["light soy sauce", "rice wine", "ginger", "chicken breasts", "bok choy", "cornflour"]', 4, '1.00', '份', '409.50', '45.80', '19.80', '8.90', 'foodcom_source_value', '1', '["麸质", "大豆"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '84933', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
