('PUBLIC', NULL, '简易墨西哥焗菜', 'Easy Mexi Bake (Low Fat)', '["Mexi Bake"]', '["三餐"]', '[]', '[]', '[]', '["西餐"]', '[]', '["快速"]', 'This is a super-easy low fat vegetarian dish that takes only minutes to throw together, it makes a great light weeknight meal served with a small side salad, you can use stewed tomatoes in place diced and use black beans in place of kidney beans. Top this with low-fat sour cream and salsa.', '["kidney beans", "diced tomatoes", "green chilies", "corn kernels", "scallions", "cumin", "oregano", "corn tortillas", "reduced-fat cheddar cheese"]', 8, '1.00', '份', '155.30', '6.30', '1.50', '32.30', 'foodcom_source_value', '1', '["牛奶"]', 'REVIEWED', 'APPROVED', 'foodcom-recipes-and-reviews-v2', '97224', 'v2', NULL, 'NONE', NULL, NOW(), NOW()),
