INSERT IGNORE INTO `exercise_item` (source_name, source_id, source_version, name, name_en, aliases, category, body_part, target_muscles, secondary_muscles, equipment, difficulty, movement_pattern, risk_tags, alternative_group, review_status, plan_ready, instructions_zh, steps_json, media_state, media_credit, created_at, updated_at) VALUES
('gym-visual-exercises-dataset', '0251', 'main-2026-08-10', '双杠臂屈伸', 'chest dip', '["dip"]', 'chest', 'chest', '["triceps"]', '["triceps", "shoulders"]', 'body weight', '中级', '推', '["肩部压力", "肘部压力"]', 'g_chest_press', 'APPROVED', '1', '将自己置于双杠上，双臂完全伸展，身体伸直。 弯曲肘部，降低身体，直到肩膀低于肘部。 伸直手臂，将自己推回起始位置。 重复所需的重复次数。', '["将自己置于双杠上，双臂完全伸展，身体伸直。", "弯曲肘部，降低身体，直到肩膀低于肘部。", "伸直手臂，将自己推回起始位置。", "重复所需的重复次数。"]', 'NONE', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
('gym-visual-exercises-dataset', '0276', 'main-2026-08-10', '死虫式', 'dead bug', '["dead bug"]', 'waist', 'waist', '["hip flexors"]', '["hip flexors", "lower back"]', 'body weight', '入门', '核心', '["腰部压力"]', 'g_core', 'APPROVED', '1', '平躺，双臂伸向天花板。 弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。 接合你的核心和下背部，将你的下背部压入地面。 慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。 暂停片刻，然后回到起始位置。 用左臂和右腿重复该动作。 继续交替进行所需的重复次数。', '["平躺，双臂伸向天花板。", "弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。", "接合你的核心和下背部，将你的下背部压入地面。", "慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。", "暂停片刻，然后回到起始位置。", "用左臂和右腿重复该动作。", "继续交替进行所需的重复次数。"]', 'NONE', '© Gym visual — https://gymvisual.com/', NOW(), NOW()),
